            raise TypeError(
                f"{name}['summary'] must be a list, got "
                f"{type(summary).__name__}"
            )
        if len(summary) != 6:
            raise ValueError(
                f"{name}['summary'] must have exactly 6 items, got "
                f"{len(summary)}"
            )
        attempts_count = _non_negative_int(
            f"{name}['summary'][0]", summary[0]
        )
        summary_completed = _non_negative_int(
            f"{name}['summary'][1]", summary[1]
        )
        summary_failed = _non_negative_int(
            f"{name}['summary'][2]", summary[2]
        )
        summary_retry = _non_negative_int(
            f"{name}['summary'][3]", summary[3]
        )
        if not isinstance(summary[4], int) or isinstance(summary[4], bool):
            raise TypeError(
                f"{name}['summary'][4] must be a non-bool int, got "
                f"{type(summary[4]).__name__}"
            )
        if not isinstance(summary[5], int) or isinstance(summary[5], bool):
            raise TypeError(
                f"{name}['summary'][5] must be a non-bool int, got "
                f"{type(summary[5]).__name__}"
            )

        if attempts_count != len(history):
            raise ValueError(
                f"{name}['summary'][0] must equal the history length "
                f"{len(history)}, got {attempts_count}"
            )
        if summary_completed != seg_completed:
            raise ValueError(
                f"{name}['summary'][1] must equal the sum of completed "
                f"{seg_completed}, got {summary_completed}"
            )
        if summary_failed != seg_failed:
            raise ValueError(
                f"{name}['summary'][2] must equal the failed count "
                f"{seg_failed}, got {summary_failed}"
            )
        seg_retry = sum(1 for entry in history if entry[3])
        if summary_retry != seg_retry:
            raise ValueError(
                f"{name}['summary'][3] must equal the retry count "
                f"{seg_retry}, got {summary_retry}"
            )
        if summary[4] != state[1]:
            raise ValueError(
                f"{name}['summary'][4] must equal state[1] "
                f"{state[1]}, got {summary[4]}"
            )
        if summary[5] != state[2]:
            raise ValueError(
                f"{name}['summary'][5] must equal state[2] "
                f"{state[2]}, got {summary[5]}"
            )

        return audit

    p = _validate(previous, "previous")
    c = _validate(current, "current")

    p_history = p["history"]
    c_history = c["history"]
    p_state = p["state"]
    c_state = c["state"]

    if len(c_history) < len(p_history):
        raise ValueError(
            "current['history'] must have previous['history'] as a prefix: "
            f"{len(c_history)} entries cannot cover {len(p_history)}"
        )
    for index, p_entry in enumerate(p_history):
        if c_history[index] != p_entry:
            raise ValueError(
                f"current['history'][{index}] must equal "
                f"previous['history'][{index}] (the previous history must "
                f"be a prefix), got {c_history[index]!r} vs {p_entry!r}"
            )

    suffix = c_history[len(p_history):]
    if len(suffix) > 0:
        first_checkpoint = suffix[0][4]
        expected_triple = [
            p_state[0],
            p_state[1],
            p_state[2] - first_checkpoint["delta"],
        ]
        actual_triple = [
            first_checkpoint["from_cursor"],
            first_checkpoint["old_done"],
            first_checkpoint["remaining"],
        ]
        if actual_triple != expected_triple:
            raise RuntimeError(
                "the first new checkpoint must continue the previous state "
                f"{p_state!r}: expected [from_cursor, old_done, "
                f"remaining] {expected_triple!r}, got {actual_triple!r}"
            )
    elif c_state != p_state:
        raise RuntimeError(
            "current adds no history entries but its state "
            f"{c_state!r} does not equal the previous state {p_state!r}"
        )

    p_summary = p["summary"]
    c_summary = c["summary"]
    delta = [c_summary[k] - p_summary[k] for k in range(6)]
    if any(value < 0 for value in delta):
        raise RuntimeError(
            "every summary delta except remaining must be >= 0, got "
            f"{delta!r}"
        )
    remaining_delta = c_state[2] - p_state[2]
    if remaining_delta > 0:
        raise RuntimeError(
            "the remaining summary delta must be <= 0, got "
            f"{remaining_delta}"
        )
    delta.append(remaining_delta)

    def _retry_chains(history: list) -> list:
        chains = []
        chain_start = 0
        while chain_start < len(history):
            if not history[chain_start][3]:
                chain_start += 1
                continue
            chain_end = chain_start
            while (
                chain_end + 1 < len(history)
                and history[chain_end + 1][3]
            ):
                chain_end += 1
            chains.append(
                [
                    chain_start,
                    chain_end,
                    list(range(chain_start, chain_end + 1)),
                ]
            )
            chain_start = chain_end + 1
        return chains

    p_chains = _retry_chains(p_history)
    c_chains = _retry_chains(c_history)
    p_chain_keys = {_freeze(chain) for chain in p_chains}
    c_chain_keys = {_freeze(chain) for chain in c_chains}
    c_only_chains = [
        _copy(chain)
        for chain in c_chains
        if _freeze(chain) not in p_chain_keys
    ]
    p_only_chains = [
        _copy(chain)
        for chain in p_chains
        if _freeze(chain) not in c_chain_keys
    ]

    return {
        "states": _copy(c_state),
        "delta": delta,
        "history": _copy(suffix),
        "retries": [c_only_chains, p_only_chains],
    }


